-- ============================================================
-- 0003_newsletter_campaigns.sql
-- ============================================================

-- ---------------------------------------------------------------------------
-- 0003_newsletter_campaigns.sql
-- ---------------------------------------------------------------------------
-- Admin can already collect newsletter subscribers but had no way to
-- email them. This migration adds the campaign queue + per-recipient
-- send log so admins can compose, queue, and ship campaigns.
--
-- Run once after 0002_services.sql:
--   mysql -u <user> -p <db> < database/migrations/0003_newsletter_campaigns.sql
--
-- Sender is intentionally simple: cron (or manual admin action) walks
-- through queued campaigns and sends each recipient one by one. For
-- bigger lists, swap to a real ESP (SendGrid, SES, Postmark) later.
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS `newsletter_campaigns` (
    `campaign_id`     BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `subject`         VARCHAR(255) NOT NULL,
    `body_html`       MEDIUMTEXT  NOT NULL,
    `from_name`       VARCHAR(160) NULL,
    `from_address`    VARCHAR(255) NULL,
    `status`          ENUM('draft','queued','sending','sent','failed','canceled')
                          NOT NULL DEFAULT 'draft',
    `total_recipients` INT UNSIGNED NOT NULL DEFAULT 0,
    `sent_count`      INT UNSIGNED NOT NULL DEFAULT 0,
    `failed_count`    INT UNSIGNED NOT NULL DEFAULT 0,
    `scheduled_at`    DATETIME NULL,
    `started_at`      DATETIME NULL,
    `finished_at`     DATETIME NULL,
    `created_by`      BIGINT UNSIGNED NULL,
    `created_at`      DATETIME NOT NULL,
    `updated_at`      DATETIME NOT NULL,
    PRIMARY KEY (`campaign_id`),
    KEY `nc_status_idx` (`status`),
    KEY `nc_scheduled_idx` (`scheduled_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `newsletter_campaign_sends` (
    `send_id`     BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `campaign_id` BIGINT UNSIGNED NOT NULL,
    `email`       VARCHAR(255) NOT NULL,
    `status`      ENUM('pending','sent','failed','skipped')
                       NOT NULL DEFAULT 'pending',
    `error`       VARCHAR(500) NULL,
    `sent_at`     DATETIME NULL,
    `created_at`  DATETIME NOT NULL,
    PRIMARY KEY (`send_id`),
    KEY `ncs_campaign_idx` (`campaign_id`, `status`),
    UNIQUE KEY `ncs_campaign_email_uq` (`campaign_id`, `email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ============================================================
-- 0004_rate_limits.sql
-- ============================================================

-- ---------------------------------------------------------------------------
-- 0004_rate_limits.sql
-- ---------------------------------------------------------------------------
-- Backing table for the Rate_limit library (application/libraries/
-- Rate_limit.php). One row per (action, identifier) sliding-window
-- bucket. Rows older than their window_end are garbage-collected
-- opportunistically by the library and via the maintenance task in
-- application/controllers/Sitemap.php style cron, if scheduled.
--
-- Run once after 0003:
--   mysql -u <user> -p <db> < database/migrations/0004_rate_limits.sql
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS `rate_limits` (
    `id`            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `bucket_key`    VARCHAR(180) NOT NULL,
    `attempts`      INT UNSIGNED NOT NULL DEFAULT 0,
    `window_start`  DATETIME NOT NULL,
    `window_end`    DATETIME NOT NULL,
    `last_ip`       VARCHAR(45) NULL,
    `created_at`    DATETIME NOT NULL,
    `updated_at`    DATETIME NOT NULL,
    PRIMARY KEY (`id`),
    UNIQUE KEY `rate_limits_bucket_uq` (`bucket_key`),
    KEY `rate_limits_window_end_idx` (`window_end`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ============================================================
-- 0005_admin_roles.sql
-- ============================================================

-- ---------------------------------------------------------------------------
-- 0005_admin_roles.sql
-- ---------------------------------------------------------------------------
-- Minimal role system for the admin table so sub-admins can exist
-- without inheriting full super-admin powers. The existing
-- admin_user_options / admin_type columns were vestigial — keeping
-- them in place but ignoring them in code.
--
-- Roles:
--   super_admin — full access (manages other admins, billing, etc.)
--   editor      — content management (listings, news, events, blogs,
--                 services, classifieds) + service requests +
--                 newsletter campaigns
--
-- The seeded admin (admin_id = 1) is upgraded to super_admin. Any
-- new sub-admin defaults to 'editor' unless explicitly set otherwise.
--
-- Run once after 0004:
--   mysql -u <user> -p <db> < database/migrations/0005_admin_roles.sql
-- ---------------------------------------------------------------------------

DROP PROCEDURE IF EXISTS pearland411_add_admin_role;
CREATE PROCEDURE pearland411_add_admin_role()
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME = 'admin'
          AND COLUMN_NAME = 'role'
    ) THEN
        ALTER TABLE `admin`
            ADD COLUMN `role` ENUM('super_admin','editor') NOT NULL DEFAULT 'editor'
                AFTER `admin_type`;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME = 'admin'
          AND COLUMN_NAME = 'is_active'
    ) THEN
        ALTER TABLE `admin`
            ADD COLUMN `is_active` TINYINT(1) NOT NULL DEFAULT 1
                AFTER `role`;
    END IF;
END;
CALL pearland411_add_admin_role();
DROP PROCEDURE pearland411_add_admin_role;

-- Promote the original seeded admin to super_admin so they can manage
-- the role system. Anyone else seeded later defaults to 'editor'.
UPDATE `admin` SET `role` = 'super_admin' WHERE `admin_id` = 1;

